def find_path(graph, start, goal):
    # Keep track of all visited nodes
    visited = set()
    # Keep track of all nodes to be visited, start with just the start node
    to_visit = [(visited, [start])]

    # Loop as long as we still find nodes to visit
    while to_visit:
        (visited, path) = to_visit.pop()
        node = path[-1]

        if node not in visited:
            neibs = graph.get(node, [])
            for next_node in neibs:
                if next_node not in visited:
                    new_path = list(path)
                    new_path.append(next_node)
                    if next_node == goal:
                        return new_path
                    else:
                        to_visit.append((visited | {next_node}, new_path))
    return None
