def find_path(graph, start, goal):
    # Track visited nodes to avoid cycles
    visited = set()

    # Track path
    def track_path(path):
        visited.add(path[-1])
        if path[-1] == goal:
            return path
        for next_node in graph.get(path[-1], []):
            if next_node not in visited:
                result = track_path(path + [next_node])
                if result:
                    return result
        return None

    # Start the recursive path tracking
    return track_path([start])
