    def _find_path(graph, current, visited, path, target):
        visited.add(current)
        visited.update(path)
        path.add(current)
        if current == target:
            return path
        for next_node in graph.get(current, []):
            if next_node not in visited:
                result = _find_path(graph, next_node, visited, path, target)
                if result:
                    return result
        path.remove(current)
        visited.discard(current)
        return None

    visited = set()
    path = {start}
