def find_path(graph, start, goal):
    def _find_path_helper(path, visited, recursion_depth):
        visited.add(path[-1])
        if path[-1] == goal:
            return path
        path_to_check = {k: v for k, v in graph.items() if k not in visited}
        for node in sorted(path_to_check, key=lambda node: len(graph[node]), reverse=True):
            if len(path_to_check[node]) == 0 or recursion_depth < 1:
                break
            result = _find_path_helper(path + [node], visited.copy(), recursion_depth - 1)
            if result:
                return result
        return None

    if start not in graph:
        return None
    return _find_path_helper([start], set(), len(graph) * 10)
