def find_path(graph, start, goal):
    # Keep track of visited nodes
    visited = set()
    # Keep track of nodes for recursion
    recursion_stack = [start]
    # Keep track of visited nodes for recursion
    recursion_visited = set()

    # Recursion helper function
    def recursive_search(node):
        visited.add(node)
        if node == goal:
            return [node]
        for neighbor in graph[node]:
            if neighbor not in visited:
                stack = recursion_stack.copy()
                visited.update(stack)
                stack.append(neighbor)
                return_stack = recursive_search(neighbor)
                if return_stack is not None:
                    return_stack.append(node)
                    return return_stack
        return None

    while recursion_stack:
        current = recursion_stack.pop()
        if current not in recursion_visited:
            recursion_visited.add(current)
            if current in graph:
                for neighbor in graph[current]:
                    if neighbor not in visited:
                        recursion_stack.append(neighbor)
                        break
        else:
            if current == goal:
                return recursive_search(current)

    return None
