def find_path(graph, start, goal):
    # Keep track of visited nodes
    visited = set()
    # Keep track of paths
    stack = []
    # Keep track of last visited nodes
    parent = {}

    # Initialize stack
    stack.append(start)
    parent[start] = None

    while stack:
        node = stack.pop()
        visited.add(node)
        if node == goal:
            break
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                stack.append(neighbor)
                parent[neighbor] = node

    # Reconstruct the path if found
    if goal in parent:
        path = [goal]
        while path[-1] != start:
            path.append(parent[path[-1]])
        path.reverse()
        return path
    else:
        return None
