def find_path(graph, start, goal):
    if start == goal:
        return [start]

    # Keep track of visited nodes
    visited = set()

    # Keep track of nodes to visit (stack)
    stack = []

    # Check if start is visited
    if start not in visited:
        visited.add(start)
        stack.append(start)

        while stack:
            current = stack.pop()
            if current == goal:
                return build_path(graph, start, goal)

            for neighbor in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    return None

def build_path(graph, start, goal):
    path = []
    current = goal
    while current != start:
        path.append(current)
        if current in graph:
            current = next((node for node in graph[current] if node in visited), None)
        else:
            return None
    path.append(start)
    path.reverse()
    return path

