def find_path(graph, start, goal):
    stack = [(set([start]), set([start]), [start])]  # visited, stack, path
    while stack:
        visited, stack, path = stack.pop()  # last popped
        if path[-1] == goal:
            return path
        for node in graph[path[-1]]:
